/// Wonky Slides' localizations (suite 11 §4): ARB files in this folder,
/// generated by `flutter gen-l10n` (`l10n.yaml`) into `gen/`.
///
/// Widgets use [slidesL10n]; code without a `BuildContext` (controllers,
/// commands, toasts) uses [slidesL10nOf] with the shell services.
library;

import 'package:flutter/widgets.dart';
import 'package:wonky_app/wonky_app.dart';

import 'gen/slides_localizations.dart';

export 'gen/slides_localizations.dart';

/// The Slides strings for [context] (English when the delegate is missing).
SlidesLocalizations slidesL10n(BuildContext context) =>
    Localizations.of<SlidesLocalizations>(context, SlidesLocalizations) ??
    slidesL10nEnglish;

/// The Slides strings in the shell's current locale (no `BuildContext`).
SlidesLocalizations slidesL10nOf(ShellServices services) {
  final c = services.navigatorContext;
  return c == null ? slidesL10nEnglish : slidesL10n(c);
}

/// English strings (the template locale).
final SlidesLocalizations slidesL10nEnglish = lookupSlidesLocalizations(
  const Locale('en'),
);
